def heap_sort(arr):
    n=len(arr)
    def h(i,e):
        while 1:
            l,r,m=2*i+1,2*i+2,i
            if l<e and arr[l]>arr[m]:m=l
            if r<e and arr[r]>arr[m]:m=r
            if m==i:break
            arr[i],arr[m]=arr[m],arr[i]
            i=m
    for i in range(n//2-1,-1,-1):h(i,n)
    for e in range(n-1,0,-1):arr[0],arr[e]=arr[e],arr[0];h(0,e)
    return arr
```

